import{_ as s,o as e,c as i,a5 as t}from"./chunks/framework.C588jwcu.js";const k=JSON.parse('{"title":"대화 상자 사용자 지정","description":"","frontmatter":{"title":"대화 상자 사용자 지정","order":4},"headers":[],"relativePath":"ko/latest/tutorial/develop/customize-the-dialogbox.md","filePath":"ko/latest/tutorial/develop/customize-the-dialogbox.md","lastUpdated":1785683504000}'),o={name:"ko/latest/tutorial/develop/customize-the-dialogbox.md"};function d(l,a,n,r,h,p){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="대화-인터페이스-사용자-지정" tabindex="-1">대화 인터페이스 사용자 지정 <a class="header-anchor" href="#대화-인터페이스-사용자-지정" aria-label="Permalink to &quot;대화 인터페이스 사용자 지정&quot;">​</a></h1><h2 id="소개" tabindex="-1">소개 <a class="header-anchor" href="#소개" aria-label="Permalink to &quot;소개&quot;">​</a></h2><p>대화 인터페이스를 사용자 지정하려면 사용할 템플릿 씬을 <code>res://ui/dialogue/</code> 같은 프로젝트 전용 디렉터리로 먼저 복사한 뒤, 그 사본이나 Godot 사용자 지정 테마를 편집하세요.</p><p><code>res://addons/konado/</code> 아래 파일을 직접 수정하지 마세요. 플러그인 업그레이드는 플러그인 디렉터리를 교체합니다. 프로젝트 소유 사본은 Konado를 업그레이드해도 유지됩니다.</p><h2 id="템플릿-파일-편집" tabindex="-1">템플릿 파일 편집 <a class="header-anchor" href="#템플릿-파일-편집" aria-label="Permalink to &quot;템플릿 파일 편집&quot;">​</a></h2><p><code>res://addons/konado/template/</code>에는 기본 대화 템플릿이 있습니다. 필요한 <code>.tscn</code>을 프로젝트로 복사하고 대화 씬에서 그 사본을 인스턴스화한 다음, 포함된 <code>KND_DialogueBox</code> 노드를 <code>KND_DialogueManager</code>의 <code>_konado_dialogue_box</code> 속성에 할당하세요.</p><p>일반적으로 노드의 스크립트는 수정하지 말고, 노드의 속성을 수정해 사용자 지정 효과를 구현하세요.</p><h2 id="음성-진행-표시-사용자-지정" tabindex="-1">음성 진행 표시 사용자 지정 <a class="header-anchor" href="#음성-진행-표시-사용자-지정" aria-label="Permalink to &quot;음성 진행 표시 사용자 지정&quot;">​</a></h2><p>일반 대사에 음성 태그가 있고 오디오가 재생 중이면 대화 상자에 재생 진행 상태가 표시됩니다. 음성이 없거나 리소스를 확인할 수 없거나 재생이 끝나면 자동으로 숨겨집니다. 필요하지 않다면 <code>KonadoDialogueBox</code> 노드의 <code>show_voice_progress</code>를 끄세요.</p><p>기본 컴포넌트 원본은 <code>res://addons/konado/template/default/voice_progress_display.tscn</code>입니다. 색상, 둥근 모서리, 크기 또는 노드 구조를 수정하기 전에 프로젝트로 복사하고 사용자 지정 대화 상자에서 그 사본을 참조하세요. 완전히 교체할 때는 다음 인터페이스를 유지해야 합니다.</p><div class="language-gdscript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gdscript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> set_progress</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(current: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, total: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> void</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> hide_progress</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> void</span></span></code></pre></div>`,11)])])}const g=s(o,[["render",d]]);export{k as __pageData,g as default};
